const $=id=>document.getElementById(id);let loaded=[],views=[],cursor=null;
function minutes(v){let a=v.split(':').map(Number);return a[0]*60+a[1];}
function dates(a,b){let start=Date.parse(a+'T00:00Z'),end=Date.parse(b+'T00:00Z');if(!Number.isFinite(start+end)||end<start||(end-start)/86400000>13)throw Error('Each range must contain 1–14 calendar dates.');let r=[];for(let t=start;t<=end;t+=86400000)r.push(new Date(t).toISOString().slice(0,10));return r;}
async function fetchRange(a,b){let q=new URLSearchParams({start:a,end:b,tf:$('tf').value});let r=await fetch('/api/candles?'+q),j=await r.json();if(!r.ok)throw Error(j.error);return j;}
$('load').onclick=async()=>{let button=$('load');try{let requestedTF=+$('tf').value;let a=dates($('a0').value,$('a1').value),b=dates($('b0').value,$('b1').value);button.disabled=true;$('status').textContent='Loading only the two selected windows…';let [da,db]=await Promise.all([fetchRange(a[0],a.at(-1)),fetchRange(b[0],b.at(-1))]);window.LabLoadedTF=requestedTF;loaded=[];for(let i=0;i<Math.max(a.length,b.length);i++){for(let [group,day,data] of [['A',a[i],da],['B',b[i],db]])if(day)loaded.push({group,day,contextBars:data.candles,bars:data.candles.filter(c=>c[0].slice(0,10)===day)});}$('status').textContent=`Loaded ${da.source_rows.toLocaleString()} + ${db.source_rows.toLocaleString()} source rows. ${$('tf').value}-minute display; empty days/slots are not filled. Session lines are references, not holiday calendars.`;render();}catch(e){$('status').textContent=e.message;}finally{button.disabled=false;}};
function render(){let from=minutes($('from').value),to=minutes($('to').value)+1;if(!Number.isFinite(from+to)||to<=from){$('status').textContent='Choose an end time later than the start, on the same ET calendar day.';return;}let rows=loaded.filter(r=>$('days').value==='all'||![0,6].includes(new Date(r.day+'T12:00Z').getUTCDay()));$('charts').replaceChildren();views=rows.map(r=>{let bars=r.bars.filter(b=>{let m=minutes(b[0].slice(11,16));return m>=from&&m<to;}),base=bars[0]?.[1]||0,div=document.createElement('div');div.className='row';let title=document.createElement('div');title.className='title';title.textContent=`${r.group} · ${new Date(r.day+'T12:00Z').toLocaleDateString('en-US',{weekday:'long',year:'numeric',month:'short',day:'numeric',timeZone:'UTC'})} · ${bars.length} candles`;let canvas=document.createElement('canvas');div.append(title,canvas);if(r.newsList){const ev=document.createElement('small');ev.textContent=r.newsList;div.append(ev);}$('charts').append(div);let v={...r,fullBars:r.bars,bars,base,canvas,from,to};canvas.onmousemove=e=>{let box=canvas.getBoundingClientRect();cursor=Math.max(from,Math.min(to,(e.clientX-box.left-8)/(box.width-90)*(to-from)+from));let nearest=bars.reduce((best,b)=>Math.abs(minutes(b[0].slice(11,16))-cursor)<Math.abs(minutes(best[0].slice(11,16))-cursor)?b:best,bars[0]);$('tip').textContent=nearest?`${r.group} ${nearest[0]} ET | O ${nearest[1]} H ${nearest[2]} L ${nearest[3]} C ${nearest[4]} | V ${nearest[5]} (nearest displayed candle) | ${LabOverlays.describe(bars,(window.LabLoadedTF||+$('tf').value),bars.indexOf(nearest))}`:'No data in this day/window';drawAll();};return v;});drawAll();}
function drawAll(){let points=$('scale').value==='points',shared=$('scale').value!=='price',globalLo=Infinity,globalHi=-Infinity;for(let v of views)for(let b of v.bars){globalLo=Math.min(globalLo,b[3]-(points?v.base:0));globalHi=Math.max(globalHi,b[2]-(points?v.base:0));}for(let v of views){let el=v.canvas,w=el.getBoundingClientRect().width,h=230,dpr=devicePixelRatio||1;el.width=w*dpr;el.height=h*dpr;let ctx=el.getContext('2d');ctx.scale(dpr,dpr);ctx.fillStyle='#192334';ctx.fillRect(0,0,w,h);if(!v.bars.length){ctx.fillStyle='#a8b9d0';ctx.fillText('No candles available for this date/window',20,80);continue;}let base=points?v.base:0,lo=shared?globalLo:Math.min(...v.bars.map(b=>b[3])),hi=shared?globalHi:Math.max(...v.bars.map(b=>b[2])),pad=Math.max(.25,(hi-lo)*.06);lo-=pad;hi+=pad;lo+=el.priceShift||0;hi+=el.priceShift||0;v.priceScale={lo,hi,base};let x=m=>8+(m-v.from)/(v.to-v.from)*(w-90),y=p=>28+(hi-p)/(hi-lo)*170;ctx.font='10px system-ui';for(let j=0;j<5;j++){let val=lo+(hi-lo)*j/4;ctx.strokeStyle='#304058';ctx.beginPath();ctx.moveTo(8,y(val));ctx.lineTo(w-80,y(val));ctx.stroke();ctx.fillStyle='#b7c6d8';ctx.fillText((points?'Δ ':'')+val.toFixed(2),w-75,y(val));}let step=v.to-v.from<=180?30:120;for(let m=Math.ceil(v.from/step)*step;m<v.to;m+=step){ctx.fillStyle='#a6b6cc';ctx.fillText(String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0'),x(m),223);}let dx=Math.max(1,(w-90)/(v.to-v.from)*(window.LabLoadedTF||+$('tf').value)*.7);for(let b of v.bars){let xx=x(minutes(b[0].slice(11,16)));ctx.strokeStyle=ctx.fillStyle=b[4]>=b[1]?'#24c9ac':'#fa6677';ctx.beginPath();ctx.moveTo(xx,y(b[2]-base));ctx.lineTo(xx,y(b[3]-base));ctx.stroke();ctx.fillRect(xx-dx/2,Math.min(y(b[1]-base),y(b[4]-base)),dx,Math.max(1,Math.abs(y(b[1]-base)-y(b[4]-base))));}if($('markers').value==='yes')for(let s of LabSessions.forDay(v.day)){if(s.minute<v.from||s.minute>=v.to)continue;ctx.strokeStyle=ctx.fillStyle=s.color;ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(x(s.minute),22);ctx.lineTo(x(s.minute),205);ctx.stroke();ctx.setLineDash([]);ctx.fillText(s.name,x(s.minute)+3,15);}const context=v.contextBars||v.fullBars,firstIndex=context.indexOf(v.bars[0]),lastIndex=context.indexOf(v.bars.at(-1)),contextX=i=>x((Date.parse(context[i][0]+'Z')-Date.parse(v.day+'T00:00Z'))/60000);LabOverlays.draw(ctx,context,(window.LabLoadedTF||+$('tf').value),firstIndex,lastIndex,contextX,y,base);LabSessionStats.draw(ctx,context,(window.LabLoadedTF||+$('tf').value),firstIndex,lastIndex,contextX,y,base);if(cursor!==null){ctx.strokeStyle='#fff';ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(x(cursor),24);ctx.lineTo(x(cursor),205);ctx.stroke();ctx.setLineDash([]);}}}
window.addEventListener('lab-overlays',drawAll);$('view').onclick=render;window.addEventListener('resize',drawAll);
</script><script src="enhance.js?v=desk-20261108"></script></html>
